    Seminar = apps.get_model("content", "Seminar")
    Speaker = apps.get_model("content", "Speaker")
    SeminarSpeaker = apps.get_model("content", "SeminarSpeaker")

    names = set(Video.objects.exclude(playlist="").values_list("playlist", flat=True))
    for name in names:
        titre = (name or "Témoignages")[:120]
        slug = slugify(titre) or "playlist"
        base, n = slug, 2
        while Playlist.objects.filter(slug=slug).exclude(titre=titre).exists():
            slug = f"{base}-{n}"
            n += 1
        pl, _ = Playlist.objects.get_or_create(
            titre=titre, defaults={"slug": slug, "ordre": 1, "is_published": True}
        )
        Video.objects.filter(playlist=name).update(playlist_ref_id=pl.id)

    for seminar in Seminar.objects.all():
        slugs = seminar.speaker_slugs or []
        if not isinstance(slugs, list):
            continue
        for i, slug in enumerate(slugs, start=1):
            speaker = Speaker.objects.filter(slug=slug).first()
            if not speaker:
                continue
            SeminarSpeaker.objects.get_or_create(
                seminar=seminar,
                speaker=speaker,
                defaults={"ordre": i},
            )


